// BuyerAppServiceHandler is an implementation of the hawkr.buyer.v1alpha1.BuyerAppService service.
type BuyerAppServiceHandler interface {
	// GetProfile 回傳呼叫者的買家 profile。
	GetProfile(context.Context, *connect.Request[v1alpha1.GetProfileRequest]) (*connect.Response[v1alpha1.GetProfileResponse], error)
	// UpdateProfile 修改 profile 的欄位（update_mask），含頭像（avatar_staged_token）。etag 必填；換頭像與文字欄位在
	// 同一個版本條件下一起寫入，任何一項失敗都不會寫入；沒有任何欄位改變時不寫入，etag 不變。
	UpdateProfile(context.Context, *connect.Request[v1alpha1.UpdateProfileRequest]) (*connect.Response[v1alpha1.UpdateProfileResponse], error)
	// ListAddresses 列出收貨地址，預設地址在最前，其餘依修改時間新到舊。每個買家最多 20 筆（見 CreateAddress），
	// 預設頁大小等於上限，所以通常一頁就是完整清單；client 仍要照 next_page_token 讀到底，上限調整時不會被截斷。
	ListAddresses(context.Context, *connect.Request[v1alpha1.ListAddressesRequest]) (*connect.Response[v1alpha1.ListAddressesResponse], error)
	// GetAddress 回傳一筆收貨地址。
	GetAddress(context.Context, *connect.Request[v1alpha1.GetAddressRequest]) (*connect.Response[v1alpha1.GetAddressResponse], error)
	// CreateAddress 新增收貨地址。第一筆地址自動成為預設地址。每個買家最多 20 筆：已有 20 筆時回
	// failed_precondition（帶 LocalizedMessage），要先刪掉一筆。
	CreateAddress(context.Context, *connect.Request[v1alpha1.CreateAddressRequest]) (*connect.Response[v1alpha1.CreateAddressResponse], error)
	// UpdateAddress 修改收貨地址。default_address 設為 true 時取代原本的預設地址；有地址時一定有一筆預設，
	// 所以不能把預設地址改成 false，要改選另一筆。
	UpdateAddress(context.Context, *connect.Request[v1alpha1.UpdateAddressRequest]) (*connect.Response[v1alpha1.UpdateAddressResponse], error)
	// DeleteAddress 刪除收貨地址。刪掉的是預設地址時，最近修改的另一筆成為預設。
	DeleteAddress(context.Context, *connect.Request[v1alpha1.DeleteAddressRequest]) (*connect.Response[v1alpha1.DeleteAddressResponse], error)
	// ListFavorites 列出收藏的商品，新到舊。
	ListFavorites(context.Context, *connect.Request[v1alpha1.ListFavoritesRequest]) (*connect.Response[v1alpha1.ListFavoritesResponse], error)
	// CheckFavorite 回傳商品是否已收藏。
	CheckFavorite(context.Context, *connect.Request[v1alpha1.CheckFavoriteRequest]) (*connect.Response[v1alpha1.CheckFavoriteResponse], error)
	// BatchCheckFavorites 回傳畫面上已收藏的商品 ID；一次最多 100 個。
	BatchCheckFavorites(context.Context, *connect.Request[v1alpha1.BatchCheckFavoritesRequest]) (*connect.Response[v1alpha1.BatchCheckFavoritesResponse], error)
	// AddFavorite 收藏商品；已收藏時也成功。帳號在刪除流程中（等待訂單完成）時回 failed_precondition。
	AddFavorite(context.Context, *connect.Request[v1alpha1.AddFavoriteRequest]) (*connect.Response[v1alpha1.AddFavoriteResponse], error)
	// RemoveFavorite 取消收藏；沒有收藏時也成功。
	RemoveFavorite(context.Context, *connect.Request[v1alpha1.RemoveFavoriteRequest]) (*connect.Response[v1alpha1.RemoveFavoriteResponse], error)
	// ListFollows 列出追蹤的店家，新到舊。
	ListFollows(context.Context, *connect.Request[v1alpha1.ListFollowsRequest]) (*connect.Response[v1alpha1.ListFollowsResponse], error)
	// CheckFollow 回傳是否已追蹤店家。
	CheckFollow(context.Context, *connect.Request[v1alpha1.CheckFollowRequest]) (*connect.Response[v1alpha1.CheckFollowResponse], error)
	// BatchCheckFollows 回傳畫面上已追蹤的店家 ID；一次最多 100 個。
	BatchCheckFollows(context.Context, *connect.Request[v1alpha1.BatchCheckFollowsRequest]) (*connect.Response[v1alpha1.BatchCheckFollowsResponse], error)
	// FollowStore 追蹤店家；已追蹤時也成功。店家不存在或不公開時回 not_found，追蹤自己的店回 invalid_argument，
	// 帳號在刪除流程中時回 failed_precondition。
	FollowStore(context.Context, *connect.Request[v1alpha1.FollowStoreRequest]) (*connect.Response[v1alpha1.FollowStoreResponse], error)
	// UnfollowStore 取消追蹤；沒有追蹤時也成功。
	UnfollowStore(context.Context, *connect.Request[v1alpha1.UnfollowStoreRequest]) (*connect.Response[v1alpha1.UnfollowStoreResponse], error)
	// ListMemberCards 列出買家消費過的店家與累計消費額（會員卡），消費額高到低。
	ListMemberCards(context.Context, *connect.Request[v1alpha1.ListMemberCardsRequest]) (*connect.Response[v1alpha1.ListMemberCardsResponse], error)
	// ListSpendingRecords 列出買家在一個店家的消費紀錄，新到舊。沒有紀錄時回空的清單。
	ListSpendingRecords(context.Context, *connect.Request[v1alpha1.ListSpendingRecordsRequest]) (*connect.Response[v1alpha1.ListSpendingRecordsResponse], error)
	// ListVisits 列出瀏覽過的商品，依最後瀏覽時間新到舊。
	ListVisits(context.Context, *connect.Request[v1alpha1.ListVisitsRequest]) (*connect.Response[v1alpha1.ListVisitsResponse], error)
	// RecordVisit 記錄一次商品瀏覽；每次呼叫都算一次瀏覽，client 不自動重送。
	RecordVisit(context.Context, *connect.Request[v1alpha1.RecordVisitRequest]) (*connect.Response[v1alpha1.RecordVisitResponse], error)
	// ClearVisits 清除全部瀏覽紀錄。
	ClearVisits(context.Context, *connect.Request[v1alpha1.ClearVisitsRequest]) (*connect.Response[v1alpha1.ClearVisitsResponse], error)
	// ListRestockSubscriptions 列出等待補貨通知的商品，新到舊。通知送出或取消之後就不在清單上。
	ListRestockSubscriptions(context.Context, *connect.Request[v1alpha1.ListRestockSubscriptionsRequest]) (*connect.Response[v1alpha1.ListRestockSubscriptionsResponse], error)
	// SubscribeRestock 訂閱商品的補貨通知；已訂閱時也成功。
	SubscribeRestock(context.Context, *connect.Request[v1alpha1.SubscribeRestockRequest]) (*connect.Response[v1alpha1.SubscribeRestockResponse], error)
	// UnsubscribeRestock 取消補貨通知；沒有訂閱時也成功。
	UnsubscribeRestock(context.Context, *connect.Request[v1alpha1.UnsubscribeRestockRequest]) (*connect.Response[v1alpha1.UnsubscribeRestockResponse], error)
}

